import { type ReactNode, useEffect, useState } from "react";
import { createRoot } from "react-dom/client";
import { BrowserRouter, Link, Navigate, Route, Routes, useLocation, useNavigate, useParams, useSearchParams } from "react-router-dom";
import "./style.css";

type Person = { id: string; displayName: string; staff: boolean };
let csrfToken = "";
const request = async <T,>(path: string, options?: RequestInit): Promise<T> => { const response = await fetch(path, { ...options, headers: { ...(options?.body ? { "content-type": "application/json" } : {}), ...(csrfToken ? { "x-csrf-token": csrfToken } : {}), ...(options?.headers || {}) } }); if (!response.ok) { if (response.status === 401 && path !== "/api/login" && path !== "/api/session") { csrfToken = ""; window.location.assign("/"); } const payload = await response.json().catch(() => ({})) as { error?: string | { message?: string } }; throw new Error(typeof payload.error === "string" ? payload.error : payload.error?.message || "Request failed"); } return response.status === 204 ? undefined as T : response.json() as Promise<T>; };
type FlashState = { notice?: string };
const flash = (notice: string) => ({ state: { notice } satisfies FlashState });
function FlashNotice({ notice: localNotice }: { notice?: string }) { const location = useLocation(); const navigate = useNavigate(); const [routeNotice] = useState(() => (location.state as FlashState | null)?.notice || ""); const notice = localNotice || routeNotice; useEffect(() => { if ((location.state as FlashState | null)?.notice) navigate(`${location.pathname}${location.search}${location.hash}`, { replace: true, state: null }); }, []); return notice ? <span className="flash-notice" role="status">{notice}</span> : null; }
function Protected({ children, allowPasswordChange = false }: { children: ReactNode; allowPasswordChange?: boolean }) { const [state, setState] = useState<"loading" | "ready" | "anonymous">("loading"); useEffect(() => { fetch("/api/session").then(async (response) => { if (!response.ok) return setState("anonymous"); const session = await response.json() as { csrfToken: string; passwordChangeRequired: boolean }; csrfToken = session.csrfToken; setState(session.passwordChangeRequired && !allowPasswordChange ? "anonymous" : "ready"); }).catch(() => setState("anonymous")); }, [allowPasswordChange]); if (state === "loading") return <main>Loading…</main>; return state === "ready" ? <>{children}</> : <Navigate to="/" replace />; }
function Login() { const navigate = useNavigate(); const [login, setLogin] = useState("manager"); const [password, setPassword] = useState("spike-password"); const [error, setError] = useState(""); return <main className="auth-page"><header className="site-header"><span className="organization-title">Welcome to Freehub</span><FlashNotice /><nav aria-label="Primary navigation"><Link to="/">Home</Link></nav></header><h1>Log In</h1><form onSubmit={async (event) => { event.preventDefault(); try { const result = await request<{ organizationId: string; csrfToken: string; passwordChangeRequired: boolean }>("/api/login", { method: "POST", body: JSON.stringify({ login, password }) }); csrfToken = result.csrfToken; navigate(result.passwordChangeRequired ? "/change-password" : `/organizations/${result.organizationId}`, flash("Logged in successfully")); } catch (err) { setError((err as Error).message); } }}>{error && <div className="validation-summary" role="alert"><strong>Log in failed</strong><span>{error}</span></div>}<label>Login<input value={login} onChange={(event) => setLogin(event.target.value)} /></label><label>Password<input type="password" value={password} onChange={(event) => setPassword(event.target.value)} /></label><button>Log in</button></form><section className="account-recovery"><h2>Forgot username or password?</h2><p>Freehub accounts are provisioned by an administrator. Ask your organization manager to reset your account and issue a temporary password.</p></section></main>; }
function ChangePassword() { const navigate = useNavigate(); const [password, setPassword] = useState(""); const [error, setError] = useState(""); return <main className="auth-page"><header className="site-header"><span className="organization-title">Welcome to Freehub</span><nav aria-label="Primary navigation"><Link to="/">Home</Link></nav></header><h1>Change your temporary password</h1><form onSubmit={async (event) => { event.preventDefault(); try { await request("/api/password", { method: "POST", body: JSON.stringify({ password }) }); const organizations = await request<{ id: string }[]>("/api/organizations"); navigate(`/organizations/${organizations[0].id}`, flash("Password was successfully updated.")); } catch (err) { setError((err as Error).message); } }}><label>New password<input type="password" minLength={12} value={password} onChange={(event) => setPassword(event.target.value)} /></label><button>Save password</button>{error && <p role="alert">{error}</p>}</form></main>; }
function Account() { const { organizationId = "" } = useParams(); const [user, setUser] = useState<{ id: string; login: string; name: string; email: string } | null>(null); const [message, setMessage] = useState(""); useEffect(() => { request<typeof user>("/api/users/me").then(setUser).catch((error) => setMessage(error.message)); }, []); return <main><OrganizationNav organizationId={organizationId} notice={message} />{user ? <><h1>{user.name}</h1><dl className="detail-list"><dt>Login</dt><dd>{user.login}</dd><dt>Email</dt><dd>{user.email}</dd></dl><h2>Account settings</h2><form className="single-column-form" onSubmit={async (event) => { event.preventDefault(); try { setUser(await request<typeof user>("/api/users/me", { method: "PUT", body: JSON.stringify({ name: user.name, email: user.email }) })); setMessage("User was successfully updated."); } catch (error) { setMessage((error as Error).message); } }}><label>Name<input value={user.name} onChange={(event) => setUser({ ...user, name: event.target.value })} /></label><label>Email<input type="email" value={user.email} onChange={(event) => setUser({ ...user, email: event.target.value })} /></label><button>Update account</button></form><p><Link to="/change-password">Change password</Link></p></> : <p>{message || "Loading account…"}</p>}</main>; }
function OrganizationNav({ organizationId, notice }: { organizationId: string; notice?: string }) { const navigate = useNavigate(); const today = new Date().toISOString().slice(0, 10); const [organizationName, setOrganizationName] = useState("Freehub"); const [identity, setIdentity] = useState({ login: "", name: "" }); useEffect(() => { Promise.all([request<{ name: string }>(`/api/organizations/${organizationId}/settings`), request<{ login: string; name: string; csrfToken: string }>("/api/session")]).then(([settings, session]) => { csrfToken = session.csrfToken; setOrganizationName(settings.name); setIdentity(session); }).catch(() => undefined); }, [organizationId]); const logout = async () => { await request("/api/logout", { method: "POST" }); csrfToken = ""; navigate("/", flash("You have been logged out.")); }; return <header className="site-header"><Link className="organization-title" to={`/organizations/${organizationId}`}>{organizationName}</Link><FlashNotice notice={notice} /><div className="session-links">{identity.login && <span>Hello {identity.name} (<Link to={`/organizations/${organizationId}/account`}>{identity.login}</Link>)</span>}<button className="link-button" type="button" onClick={logout}>Log Out</button></div><nav aria-label="Primary navigation"><Link to={`/organizations/${organizationId}`}>Home</Link><Link to={`/organizations/${organizationId}/visits/days/${today}`}>Visits</Link><Link to={`/organizations/${organizationId}/reports`}>Reports</Link><Link to={`/organizations/${organizationId}/imports`}>Import</Link><Link to={`/organizations/${organizationId}/bulk-management`}>Manage people</Link><Link to={`/organizations/${organizationId}/settings`}>Settings</Link></nav></header>; }
function BulkManagement() { const { organizationId = "" } = useParams(); const [filter, setFilter] = useState({ createdAfter: "", createdBefore: "", lastVisitAfter: "", lastVisitBefore: "", neverVisited: false, archived: false }); const [result, setResult] = useState<{ count: number; rows: { id: string; displayName: string; createdAt: string; lastVisitAt: string | null }[]; truncated: boolean } | null>(null); const [message, setMessage] = useState(""); const requestFilter = () => Object.fromEntries(Object.entries(filter).filter(([, value]) => value !== "" && value !== false)); const query = () => new URLSearchParams(Object.entries(requestFilter()).map(([key, value]) => [key, String(value)])).toString(); const preview = async () => { try { setResult(await request(`/api/organizations/${organizationId}/bulk-people?${query()}`)); setMessage(""); } catch (err) { setMessage((err as Error).message); } }; const mutate = async (action: "archive" | "restore") => { try { const value = await request<{ count: number }>(`/api/organizations/${organizationId}/bulk-people/${action}`, { method: "POST", body: JSON.stringify(requestFilter()) }); setMessage(`${value.count} people ${action}d.`); await preview(); } catch (err) { setMessage((err as Error).message); } }; return <main><OrganizationNav organizationId={organizationId} /><h1>Manage people</h1><p>Preview a filtered selection before archiving or restoring it. These actions are reversible.</p><label>Created after<input type="date" value={filter.createdAfter} onChange={(event) => setFilter({ ...filter, createdAfter: event.target.value })} /></label><label>Created before<input type="date" value={filter.createdBefore} onChange={(event) => setFilter({ ...filter, createdBefore: event.target.value })} /></label><label>Last visit after<input type="date" value={filter.lastVisitAfter} onChange={(event) => setFilter({ ...filter, lastVisitAfter: event.target.value })} /></label><label>Last visit before<input type="date" value={filter.lastVisitBefore} onChange={(event) => setFilter({ ...filter, lastVisitBefore: event.target.value })} /></label><label><input type="checkbox" checked={filter.neverVisited} onChange={(event) => setFilter({ ...filter, neverVisited: event.target.checked })} /> Never visited</label><label><input type="checkbox" checked={filter.archived} onChange={(event) => setFilter({ ...filter, archived: event.target.checked })} /> Archived people</label><button onClick={preview}>Preview selection</button>{message && <p role="status">{message}</p>}{result && <section><h2>{result.count} people selected</h2><a href={`/api/organizations/${organizationId}/bulk-people.csv?${query()}`}>Export selection</a><ul>{result.rows.map((person) => <li key={person.id}><Link to={`/organizations/${organizationId}/people/${person.id}`}>{person.displayName}</Link></li>)}</ul>{result.truncated && <p>Showing the first 250 people; export includes all selected people.</p>}<button onClick={() => mutate(filter.archived ? "restore" : "archive")}>{filter.archived ? "Restore selection" : "Archive selection"}</button></section>}</main>; }
type ImportJob = { id: string; format: string; status: string; summary: { creates: number; matches: number; rejected: number }; rows: { rowNumber: number; displayName: string | null; disposition: string; createdPersonId: string | null; matchedPersonId: string | null; errors: string[]; warnings: string[] }[] };
const base64 = async (file: File) => { const bytes = new Uint8Array(await file.arrayBuffer()); let result = ""; for (const byte of bytes) result += String.fromCharCode(byte); return btoa(result); };
function Imports() { const { organizationId = "" } = useParams(); const [file, setFile] = useState<File | null>(null); const [sourceBase64, setSourceBase64] = useState(""); const [job, setJob] = useState<ImportJob | null>(null); const [error, setError] = useState(""); const preview = async (event: React.FormEvent) => { event.preventDefault(); try { if (!file) throw new Error("Choose a CSV file"); const source = await base64(file); setSourceBase64(source); setJob(await request<ImportJob>(`/api/organizations/${organizationId}/imports/preview`, { method: "POST", body: JSON.stringify({ sourceBase64: source }) })); setError(""); } catch (err) { setError((err as Error).message); } }; const apply = async () => { try { if (!job) return; setJob(await request<ImportJob>(`/api/organizations/${organizationId}/imports/${job.id}/apply`, { method: "POST", body: JSON.stringify({ sourceBase64 }) })); setError(""); } catch (err) { setError((err as Error).message); } }; return <main><OrganizationNav organizationId={organizationId} /><h1>Import people</h1><p>Upload the documented Freehub CSV template or a Corsizio export. Existing matches are skipped; no existing person is changed.</p><p><a href="/freehub-import-template.csv" download>Download Freehub template</a></p><form onSubmit={preview}><label>CSV file<input aria-label="CSV file" type="file" accept=".csv,text/csv" onChange={(event) => setFile(event.target.files?.[0] || null)} /></label><button>Preview import</button></form>{error && <p role="alert">{error}</p>}{job && <section><h2>{job.status === "applied" ? "Import results" : "Preview"}</h2><p>{job.summary.creates} to create, {job.summary.matches} existing matches to skip, {job.summary.rejected} rejected.</p>{job.status === "applied" && <p role="status">Import applied. Created people are linked below; existing matches were not changed.</p>}<ul>{job.rows.map((row) => <li key={row.rowNumber}>Row {row.rowNumber}{row.displayName ? ` — ${row.displayName}` : ""}: {row.disposition}{row.createdPersonId && <> — <Link to={`/organizations/${organizationId}/people/${row.createdPersonId}`}>View created person</Link></>}{row.matchedPersonId && <> — <Link to={`/organizations/${organizationId}/people/${row.matchedPersonId}`}>View existing person</Link></>}{row.errors.length ? ` — ${row.errors.join("; ")}` : ""}{row.warnings.length ? ` (${row.warnings.join("; ")})` : ""}</li>)}</ul>{job.summary.rejected > 0 && <a href={`/api/organizations/${organizationId}/imports/${job.id}/rejections.csv`}>Download rejection report</a>}{job.status === "previewed" && <button onClick={apply}>Confirm import</button>}</section>}</main>; }
function People() { const { organizationId = "" } = useParams(); const [query, setQuery] = useState(""); const [archived, setArchived] = useState(false); const [people, setPeople] = useState<Person[]>([]); const [error, setError] = useState(""); useEffect(() => { if (query.trim().length < 2) { setPeople([]); setError(""); return; } request<Person[]>(`/api/organizations/${organizationId}/people${archived ? "/archived" : ""}?q=${encodeURIComponent(query)}`).then(setPeople).catch((err) => setError(err.message)); }, [organizationId, query, archived]); return <main><OrganizationNav organizationId={organizationId} /><h1>{archived ? "Find an archived person" : "Add a person to the queue"}</h1><label>Name<input aria-label="Search people" value={query} onChange={(event) => setQuery(event.target.value)} /></label><p>Start typing to find a person or <Link to={`/organizations/${organizationId}/people/new`}>add a new person</Link>.</p><label><input type="checkbox" checked={archived} onChange={(event) => setArchived(event.target.checked)} /> Search archived people</label>{error && <p role="alert">{error}</p>}<ul>{people.map((person) => <li key={person.id}><Link to={`/organizations/${organizationId}/people/${person.id}`}>{person.displayName}</Link>{person.staff ? " (Staff)" : ""}</li>)}</ul></main>; }
const supportedTimezones = ["America/Chicago", "America/Denver", "America/Los_Angeles", "America/New_York", "America/Phoenix", "America/Toronto", "UTC"];
function Settings() { const { organizationId = "" } = useParams(); const [settings, setSettings] = useState<{ name: string; key: string; timezone: string; location: string | null; canManage: boolean } | null>(null); const [error, setError] = useState(""); const [notice, setNotice] = useState(""); useEffect(() => { request<typeof settings>(`/api/organizations/${organizationId}/settings`).then(setSettings).catch((err) => setError(err.message)); }, [organizationId]); if (error && !settings) return <main><OrganizationNav organizationId={organizationId} notice={notice} /><p role="alert">{error}</p></main>; if (!settings) return <main>Loading settings…</main>; const timezones = supportedTimezones.includes(settings.timezone) ? supportedTimezones : [settings.timezone, ...supportedTimezones]; return <main><OrganizationNav organizationId={organizationId} notice={notice} /><h1>{settings.name} : Settings</h1>{settings.canManage ? <form className="single-column-form settings-form" onSubmit={async (event) => { event.preventDefault(); try { const updated = await request<typeof settings>(`/api/organizations/${organizationId}/settings`, { method: "PUT", body: JSON.stringify(settings) }); setSettings(updated); setError(""); setNotice("Organization was successfully updated."); } catch (err) { setError((err as Error).message); } }}><label>Organization Name<input value={settings.name} onChange={(event) => setSettings({ ...settings, name: event.target.value })} /><small>For example “San Francisco Bike Kitchen”.</small></label><label>Key<input value={settings.key} readOnly /><small>Used for the organization URL and cannot be changed here.</small></label><label>Location<input value={settings.location || ""} onChange={(event) => setSettings({ ...settings, location: event.target.value })} /></label><label>Timezone<select value={settings.timezone} onChange={(event) => setSettings({ ...settings, timezone: event.target.value })}>{timezones.map((timezone) => <option key={timezone}>{timezone}</option>)}</select><small>Controls reporting dates and displayed local times.</small></label><button>Update</button>{error && <p role="alert">{error}</p>}</form> : <p>You do not have permission to change organization settings.</p>}</main>; }
type PersonDraft = { firstName: string; lastName: string; email: string; phone: string; street1: string; street2: string; city: string; state: string; postalCode: string; country: string; yearOfBirth: number | ""; staff: boolean; emailOptOut: boolean };
const blankPerson = (): PersonDraft => ({ firstName: "", lastName: "", email: "", phone: "", street1: "", street2: "", city: "", state: "", postalCode: "", country: "US", yearOfBirth: "", staff: false, emailOptOut: false });
function PersonFields({ person, setPerson }: { person: PersonDraft; setPerson: (person: PersonDraft) => void }) { const text = (name: keyof PersonDraft, label: string, options: { type?: string; className?: string } = {}) => <label className={options.className}>{label}<input type={options.type || "text"} value={String(person[name] ?? "")} onChange={(event) => setPerson({ ...person, [name]: name === "yearOfBirth" ? event.target.value ? Number(event.target.value) : "" : event.target.value })} /></label>; return <div className="person-form-layout"><div className="person-form-primary"><fieldset><legend>Name <span aria-hidden="true">*</span></legend><div className="paired-fields">{text("firstName", "First")}{text("lastName", "Last")}</div></fieldset>{text("email", "Email", { type: "email" })}<label className="inline-choice"><input type="checkbox" checked={person.emailOptOut} onChange={(event) => setPerson({ ...person, emailOptOut: event.target.checked })} /> Don't send emails</label><fieldset><legend>Address</legend>{text("street1", "Street address")}{text("street2", "Address line 2")}<div className="paired-fields">{text("city", "City")}{text("state", "State / Province / Region")}</div><div className="paired-fields">{text("postalCode", "Postal / Zip code")}{text("country", "Country")}</div></fieldset></div><div className="person-form-secondary">{text("phone", "Phone number", { type: "tel" })}{text("yearOfBirth", "Year of birth", { type: "number" })}<label className="inline-choice"><input type="checkbox" checked={person.staff} onChange={(event) => setPerson({ ...person, staff: event.target.checked })} /> Staff</label></div></div>; }
function PersonForm() { const { organizationId = "" } = useParams(); const navigate = useNavigate(); const [person, setPerson] = useState<PersonDraft>(blankPerson); const [error, setError] = useState(""); return <main><OrganizationNav organizationId={organizationId} /><h1>People : New</h1><p>Only First Name is required.</p>{error && <div className="validation-summary" role="alert"><strong>There were problems with the following fields</strong><span>{error === "first name is required" ? "First name can't be blank" : error}</span></div>}<form className="person-form" onSubmit={async (event) => { event.preventDefault(); try { if (!person.firstName.trim()) { setError("first name is required"); return; } const created = await request<{ id: string }>(`/api/organizations/${organizationId}/people`, { method: "POST", body: JSON.stringify({ ...person, yearOfBirth: person.yearOfBirth || null }) }); navigate(`/organizations/${organizationId}/people/${created.id}`, flash("Person was successfully created.")); } catch (err) { setError((err as Error).message); } }}><PersonFields person={person} setPerson={setPerson} /><button>Create person</button></form></main>; }
function EditPerson() { const { organizationId = "", personId = "" } = useParams(); const navigate = useNavigate(); const [person, setPerson] = useState<PersonDraft>(blankPerson); const [error, setError] = useState(""); useEffect(() => { request<PersonDraft & { yearOfBirth: number | null }>(`/api/organizations/${organizationId}/people/${personId}`).then((value) => setPerson({ ...blankPerson(), ...value, yearOfBirth: value.yearOfBirth || "" })); }, [organizationId, personId]); return <main><OrganizationNav organizationId={organizationId} /><h1>Person : Detail</h1><p>Update this person's details or archive the record from their profile.</p><form className="person-form" onSubmit={async (event) => { event.preventDefault(); try { await request(`/api/organizations/${organizationId}/people/${personId}`, { method: "PUT", body: JSON.stringify({ ...person, yearOfBirth: person.yearOfBirth || null }) }); navigate(`/organizations/${organizationId}/people/${personId}`, flash("Person was successfully updated.")); } catch (err) { setError((err as Error).message); } }}><PersonFields person={person} setPerson={setPerson} /><button>Update person</button>{error && <p role="alert">{error}</p>}</form></main>; }
type ProfilePerson = { displayName: string; id: string; staff: boolean; email?: string | null; phone?: string | null; archivedAt?: string | null; today: string; displayRole: string; tags: { id: string; name: string }[]; visits: Visit[]; services: Service[]; membership: { state: "current" | "expired" | "none"; service: Service | null } };
function Profile() { const { organizationId = "", personId = "" } = useParams(); const navigate = useNavigate(); const [person, setPerson] = useState<ProfilePerson | null>(null); const [notes, setNotes] = useState<{ id: string; text: string; createdAt: string }[]>([]); const [activity, setActivity] = useState<"project" | "volunteering">("project"); const [note, setNote] = useState(""); const [error, setError] = useState(""); const [notice, setNotice] = useState(""); const load = async () => { try { const [value, recentNotes] = await Promise.all([request<ProfilePerson>(`/api/organizations/${organizationId}/people/${personId}`), request<typeof notes>(`/api/organizations/${organizationId}/people/${personId}/notes`)]); setPerson(value); setNotes(recentNotes); setActivity(value.staff ? "volunteering" : "project"); } catch { setPerson(null); } }; useEffect(() => { void load(); }, [organizationId, personId]); const quickSignIn = async () => { try { await request(`/api/organizations/${organizationId}/visits`, { method: "POST", body: JSON.stringify({ personId, activity, arrivedAt: new Date().toISOString(), note }) }); navigate(`/organizations/${organizationId}/visits/days/${person?.today || new Date().toISOString().slice(0, 10)}`, flash(`Visit for ${person?.displayName || "Person"} was successfully created.`)); } catch (err) { setError((err as Error).message); } }; if (!person) return <main><OrganizationNav organizationId={organizationId} /><p>Person not found</p></main>; const hours = (kind: Visit["activity"]) => person.visits.filter((visit) => visit.activity === kind).reduce((total, visit) => total + (visit.durationSeconds || 0), 0) / 3600; const membershipText = person.membership.state === "current" ? `Membership expires ${person.membership.service?.endDate || "without an end date"}` : person.membership.state === "expired" ? `Membership expired ${person.membership.service?.endDate || ""}` : "Not a member"; return <main className="person-profile"><OrganizationNav organizationId={organizationId} notice={notice} /><h1>{person.displayName}</h1><div className="profile-top"><section className="sign-in-panel"><h2>Sign {person.displayName.split(" ")[0]} In</h2><label className="inline-choice"><input type="radio" name="activity" checked={activity === "project"} onChange={() => setActivity("project")} /> Project</label><label className="inline-choice"><input type="radio" name="activity" checked={activity === "volunteering"} onChange={() => setActivity("volunteering")} /> Volunteer</label><label>Note<textarea value={note} onChange={(event) => setNote(event.target.value)} /></label><button onClick={quickSignIn}>Sign In</button></section><aside className="person-summary"><strong>{person.displayRole[0].toUpperCase() + person.displayRole.slice(1)}</strong><span>Has volunteered {hours("volunteering").toFixed(1)} hours</span><span>Has used {hours("project").toFixed(1)} project hours</span><span className={`membership-${person.membership.state}`}>{membershipText}</span>{person.membership.service ? <button onClick={async () => { try { await request(`/api/organizations/${organizationId}/services/${person.membership.service!.id}/renew`, { method: "POST", body: "{}" }); await load(); setNotice("Service was successfully renewed."); } catch (err) { setError((err as Error).message); } }}>Renew</button> : <Link to={`/organizations/${organizationId}/people/${personId}/services/new`}>Create Membership</Link>}{person.email && <span>{person.email}</span>}{person.phone && <span>{person.phone}</span>}<Link to={`/organizations/${organizationId}/people/${personId}/edit`}>Edit {person.displayName.split(" ")[0]}</Link><span className="tag-links">{person.tags.map((tag) => <Link key={tag.id} to={`/organizations/${organizationId}/tags/${tag.id}`}>{tag.name}</Link>)} <Link to={`/organizations/${organizationId}/people/${personId}/tags`}>Edit tags</Link></span></aside></div><div className="profile-columns"><section><h2>Recent Visits <Link to={`/organizations/${organizationId}/people/${personId}/visits/new`}>Add a Visit</Link></h2>{person.visits.length ? <ul>{person.visits.slice(0, 3).map((visit) => <li key={visit.id}><span>{visit.activity === "project" ? "Project" : "Volunteered"}</span><span>{((visit.durationSeconds || 0) / 3600).toFixed(1)} hours</span></li>)}</ul> : <p><em>No past visits.</em></p>}<Link to={`/organizations/${organizationId}/people/${personId}/visits`}>See All {person.visits.length} Visits with Details</Link></section><section><h2>Recent Services <Link to={`/organizations/${organizationId}/people/${personId}/services/new`}>Add A Service</Link></h2>{person.services.length ? <ul>{person.services.slice(0, 3).map((service) => <li key={service.id}><span>{serviceLabel(service.type)}</span><span>{service.endDate ? `Ends ${service.endDate}` : "No end date"}</span></li>)}</ul> : <p><em>No past services.</em></p>}<Link to={`/organizations/${organizationId}/people/${personId}/services`}>See All {person.services.length} Services with Details</Link></section></div><section className="recent-notes"><h2>Recent Notes <Link to={`/organizations/${organizationId}/people/${personId}/notes`}>Add A Note</Link></h2>{notes.length ? <ul>{notes.slice(0, 3).map((item) => <li key={item.id}><span>{new Date(item.createdAt).toLocaleDateString()}:</span><em>{item.text}</em></li>)}</ul> : <p><em>No past notes.</em></p>}<Link to={`/organizations/${organizationId}/people/${personId}/notes`}>See All {notes.length} Notes.</Link></section>{person.archivedAt ? <><p>This person is archived.</p><button onClick={async () => { await request(`/api/organizations/${organizationId}/people/${personId}/restore`, { method: "POST" }); await load(); setNotice("Person was successfully restored."); }}>Restore person</button></> : <button className="archive-action" onClick={async () => { await request(`/api/organizations/${organizationId}/people/${personId}/archive`, { method: "POST" }); await load(); setNotice("Person was successfully archived."); }}>Archive person</button>}{error && <p role="alert">{error}</p>}</main>; }
type Service = { id: string; personId: string; type: "membership" | "earn_a_bike" | "class"; startDate: string | null; endDate: string | null; paid: boolean; volunteered: boolean; createdAt?: string; updatedAt?: string; createdByUserId?: string | null; updatedByUserId?: string | null; notes?: { text: string }[] };
const serviceLabel = (type: Service["type"]) => type === "membership" ? "Membership" : type === "earn_a_bike" ? "Earn a Bike / Digging Rights" : "Class";
function PersonServices() { const { organizationId = "", personId = "" } = useParams(); const [services, setServices] = useState<Service[]>([]); const [personName, setPersonName] = useState("Person"); useEffect(() => { Promise.all([request<Service[]>(`/api/organizations/${organizationId}/people/${personId}/services`), request<{ displayName: string }>(`/api/organizations/${organizationId}/people/${personId}`)]).then(([rows, person]) => { setServices(rows); setPersonName(person.displayName); }); }, [organizationId, personId]); return <main><OrganizationNav organizationId={organizationId} /><h1><Link to={`/organizations/${organizationId}/people/${personId}`}>{personName}</Link> : Services</h1><p><Link to={`/organizations/${organizationId}/people/${personId}/services/new`}>Add a service</Link></p>{services.length ? <table><thead><tr><th>Service type</th><th>Start date</th><th>End date</th><th>Paid</th><th>Volunteered</th><th>Note</th><th>Actions</th></tr></thead><tbody>{services.map((service) => <tr key={service.id}><td>{serviceLabel(service.type)}</td><td>{service.startDate || "—"}</td><td>{service.endDate || "—"}</td><td>{service.paid ? "Yes" : "No"}</td><td>{service.volunteered ? "Yes" : "No"}</td><td>{service.notes?.map((note) => note.text).join("; ") || "—"}</td><td><Link to={`/organizations/${organizationId}/people/${personId}/services/${service.id}`}>Show</Link>{" · "}<Link to={`/organizations/${organizationId}/people/${personId}/services/${service.id}/edit`}>Edit</Link></td></tr>)}</tbody></table> : <p className="empty-state">No services.</p>}</main>; }
function ServiceForm({ edit = false }: { edit?: boolean }) { const { organizationId = "", personId = "", serviceId = "" } = useParams(); const navigate = useNavigate(); const [personName, setPersonName] = useState("Person"); const [service, setService] = useState({ type: "membership" as Service["type"], startDate: "", endDate: "", paid: false, volunteered: false, note: "" }); const [error, setError] = useState(""); useEffect(() => { request<{ displayName: string }>(`/api/organizations/${organizationId}/people/${personId}`).then((person) => setPersonName(person.displayName)); if (edit) request<Service>(`/api/organizations/${organizationId}/services/${serviceId}`).then((value) => setService({ ...service, ...value, startDate: value.startDate || "", endDate: value.endDate || "", note: value.notes?.[0]?.text || "" })).catch((err) => setError(err.message)); }, [edit, organizationId, personId, serviceId]); return <main><OrganizationNav organizationId={organizationId} /><h1><Link to={`/organizations/${organizationId}/people/${personId}`}>{personName}</Link> : Services : {edit ? "Edit" : "New"}</h1><form className="single-column-form service-form" onSubmit={async (event) => { event.preventDefault(); try { const dates = edit || service.startDate || service.endDate ? { startDate: service.startDate || null, endDate: service.endDate || null } : {}; const result = await request<Service>(edit ? `/api/organizations/${organizationId}/services/${serviceId}` : `/api/organizations/${organizationId}/people/${personId}/services`, { method: edit ? "PUT" : "POST", body: JSON.stringify({ ...service, ...dates }) }); navigate(`/organizations/${organizationId}/people/${result.personId}/services/${result.id}`, flash(edit ? "Service was successfully updated." : "Service was successfully created.")); } catch (err) { setError((err as Error).message); } }}><label>Service type<select value={service.type} onChange={(event) => setService({ ...service, type: event.target.value as Service["type"] })}><option value="membership">Membership</option><option value="earn_a_bike">Earn a Bike / Digging Rights</option><option value="class">Class</option></select></label><label>Start date<input type="date" value={service.startDate} onChange={(event) => setService({ ...service, startDate: event.target.value })} /></label><label>End date<input type="date" value={service.endDate} onChange={(event) => setService({ ...service, endDate: event.target.value })} /></label><label className="inline-choice"><input type="checkbox" checked={service.paid} onChange={(event) => setService({ ...service, paid: event.target.checked })} /> Paid</label><label className="inline-choice"><input type="checkbox" checked={service.volunteered} onChange={(event) => setService({ ...service, volunteered: event.target.checked })} /> Volunteered</label><label>Note<textarea value={service.note} onChange={(event) => setService({ ...service, note: event.target.value })} /></label><button>{edit ? "Update service" : "Create service"}</button>{error && <p role="alert">{error}</p>}</form></main>; }
function ServiceDetail() { const { organizationId = "", personId = "", serviceId = "" } = useParams(); const [service, setService] = useState<Service | null>(null); const [personName, setPersonName] = useState("Person"); useEffect(() => { Promise.all([request<Service>(`/api/organizations/${organizationId}/services/${serviceId}`), request<{ displayName: string }>(`/api/organizations/${organizationId}/people/${personId}`)]).then(([value, person]) => { setService(value); setPersonName(person.displayName); }); }, [organizationId, personId, serviceId]); return <main><OrganizationNav organizationId={organizationId} />{service ? <><h1><Link to={`/organizations/${organizationId}/people/${personId}`}>{personName}</Link> : Services : Detail</h1><dl className="detail-list"><dt>Service type</dt><dd>{serviceLabel(service.type)}</dd><dt>Start date</dt><dd>{service.startDate || "—"}</dd><dt>End date</dt><dd>{service.endDate || "—"}</dd><dt>Paid</dt><dd>{service.paid ? "Yes" : "No"}</dd><dt>Volunteered</dt><dd>{service.volunteered ? "Yes" : "No"}</dd><dt>Note</dt><dd>{service.notes?.length ? service.notes.map((note) => note.text).join("; ") : "—"}</dd>{service.createdAt && <><dt>Created</dt><dd>{displayTime(service.createdAt)}{service.createdByUserId ? ` by user ${service.createdByUserId}` : ""}</dd></>}{service.updatedAt && <><dt>Updated</dt><dd>{displayTime(service.updatedAt)}{service.updatedByUserId ? ` by user ${service.updatedByUserId}` : ""}</dd></>}</dl><Link to={`/organizations/${organizationId}/people/${personId}/services/${service.id}/edit`}>Edit service</Link></> : <p>Loading service…</p>}</main>; }
function PersonTags() { const { organizationId = "", personId = "" } = useParams(); const [tags, setTags] = useState<{ id: string; name: string; peopleCount: number }[]>([]); const [assigned, setAssigned] = useState<{ id: string; name: string }[]>([]); const [names, setNames] = useState(""); const [message, setMessage] = useState(""); const load = async () => { try { const [available, person] = await Promise.all([request<typeof tags>(`/api/organizations/${organizationId}/tags`), request<{ tags: { id: string; name: string }[] }>(`/api/organizations/${organizationId}/people/${personId}`)]); setTags(available); setAssigned(person.tags); } catch (err) { setMessage((err as Error).message); } }; useEffect(() => { void load(); }, [organizationId, personId]); const fragment = names.split(",").at(-1)?.trim().toLocaleLowerCase() || ""; const suggestions = fragment.length >= 1 ? tags.filter((tag) => tag.name.toLocaleLowerCase().includes(fragment)).slice(0, 8) : []; const choose = (name: string) => { const parts = names.split(","); parts[parts.length - 1] = ` ${name}`; setNames(`${parts.join(",").trim()}, `); }; return <main><OrganizationNav organizationId={organizationId} /><h1>Tags</h1><p>Assign tags to this person. Separate names with commas.</p><form onSubmit={async (event) => { event.preventDefault(); try { await request(`/api/organizations/${organizationId}/people/${personId}/tags`, { method: "PUT", body: JSON.stringify({ names: names.split(",").map((name) => name.trim()).filter(Boolean) }) }); setNames(""); setMessage("Tags saved."); void load(); } catch (err) { setMessage((err as Error).message); } }}><label>Tags<input aria-label="Tags" value={names} onChange={(event) => setNames(event.target.value)} autoComplete="off" /></label><button>Save tags</button></form>{suggestions.length > 0 && <ul aria-label="Tag suggestions">{suggestions.map((tag) => <li key={tag.id}><button type="button" onClick={() => choose(tag.name)}>{tag.name}</button></li>)}</ul>}{message && <p role="status">{message}</p>}<h2>Assigned tags</h2><ul>{assigned.map((tag) => <li key={tag.id}><Link to={`/organizations/${organizationId}/tags/${tag.id}`}>{tag.name}</Link> <button type="button" onClick={async () => { try { await request(`/api/organizations/${organizationId}/people/${personId}/tags/${tag.id}`, { method: "DELETE" }); void load(); } catch (err) { setMessage((err as Error).message); } }}>Remove {tag.name}</button></li>)}</ul></main>; }
function Tags() { const { organizationId = "" } = useParams(); const [tags, setTags] = useState<{ id: string; name: string; peopleCount: number }[]>([]); useEffect(() => { request<typeof tags>(`/api/organizations/${organizationId}/tags`).then(setTags); }, [organizationId]); return <main><OrganizationNav organizationId={organizationId} /><h1>All Tags</h1>{tags.length ? <table><thead><tr><th>Tag</th><th>People</th></tr></thead><tbody>{tags.map((tag) => <tr key={tag.id}><td><Link to={`/organizations/${organizationId}/tags/${tag.id}`}>{tag.name}</Link></td><td>{tag.peopleCount}</td></tr>)}</tbody></table> : <p className="empty-state">No tags.</p>}</main>; }
type Note = { id: string; text: string; personId: string | null; visitId: string | null; serviceId: string | null; createdByUserId: string | null; updatedByUserId: string | null; createdByName: string | null; updatedByName: string | null; createdAt: string; updatedAt: string };
const noteRegarding = (note: Note) => note.visitId ? `Visit ${note.visitId}` : note.serviceId ? `Service ${note.serviceId}` : "Person";
function PersonNotes() { const { organizationId = "", personId = "" } = useParams(); const [notes, setNotes] = useState<Note[]>([]); const [personName, setPersonName] = useState("Person"); const [message, setMessage] = useState(""); useEffect(() => { Promise.all([request<Note[]>(`/api/organizations/${organizationId}/people/${personId}/notes`), request<{ displayName: string }>(`/api/organizations/${organizationId}/people/${personId}`)]).then(([rows, person]) => { setNotes(rows); setPersonName(person.displayName); }).catch((err) => setMessage(err.message)); }, [organizationId, personId]); return <main><OrganizationNav organizationId={organizationId} /><h1><Link to={`/organizations/${organizationId}/people/${personId}`}>{personName}</Link> : Notes</h1><p><Link to={`/organizations/${organizationId}/people/${personId}/notes/new`}>Add a note</Link></p>{message && <p role="status">{message}</p>}{notes.length ? <table><thead><tr><th>Created</th><th>Regarding</th><th>Notable</th><th>Author</th><th>Actions</th></tr></thead><tbody>{notes.map((note) => <tr key={note.id}><td>{displayTime(note.createdAt)}</td><td>{noteRegarding(note)}</td><td>{note.text}</td><td>{note.createdByName || (note.createdByUserId ? "Unknown user" : "Imported")}</td><td><Link to={`/organizations/${organizationId}/people/${personId}/notes/${note.id}`}>Show</Link>{" · "}<Link to={`/organizations/${organizationId}/people/${personId}/notes/${note.id}/edit`}>Edit</Link></td></tr>)}</tbody></table> : <p className="empty-state">No past notes.</p>}</main>; }
function NoteForm({ edit = false }: { edit?: boolean }) { const { organizationId = "", personId = "", noteId = "" } = useParams(); const navigate = useNavigate(); const [personName, setPersonName] = useState("Person"); const [note, setNote] = useState<Note | null>(null); const [text, setText] = useState(""); const [error, setError] = useState(""); useEffect(() => { request<{ displayName: string }>(`/api/organizations/${organizationId}/people/${personId}`).then((person) => setPersonName(person.displayName)); if (edit) request<Note>(`/api/organizations/${organizationId}/notes/${noteId}`).then((value) => { setNote(value); setText(value.text); }).catch((err) => setError(err.message)); }, [edit, organizationId, personId, noteId]); return <main><OrganizationNav organizationId={organizationId} /><h1><Link to={`/organizations/${organizationId}/people/${personId}`}>{personName}</Link> : Notes : {edit ? "Edit" : "New"}</h1>{edit && note && <p><strong>Regarding:</strong> {noteRegarding(note)}</p>}<form className="single-column-form note-form" onSubmit={async (event) => { event.preventDefault(); try { const saved = await request<Note>(edit ? `/api/organizations/${organizationId}/notes/${noteId}` : `/api/organizations/${organizationId}/notes`, { method: edit ? "PUT" : "POST", body: JSON.stringify(edit ? { text } : { personId, text }) }); navigate(`/organizations/${organizationId}/people/${personId}/notes/${saved.id}`, flash(edit ? "Note was successfully updated." : "Note was successfully created.")); } catch (err) { setError((err as Error).message); } }}><label>Text<textarea value={text} onChange={(event) => setText(event.target.value)} /></label><button>{edit ? "Update note" : "Create note"}</button>{error && <p role="alert">{error}</p>}</form></main>; }
function NoteDetail() { const { organizationId = "", personId = "", noteId = "" } = useParams(); const [note, setNote] = useState<Note | null>(null); const [personName, setPersonName] = useState("Person"); useEffect(() => { Promise.all([request<Note>(`/api/organizations/${organizationId}/notes/${noteId}`), request<{ displayName: string }>(`/api/organizations/${organizationId}/people/${personId}`)]).then(([value, person]) => { setNote(value); setPersonName(person.displayName); }); }, [organizationId, personId, noteId]); return <main><OrganizationNav organizationId={organizationId} />{note ? <><h1><Link to={`/organizations/${organizationId}/people/${personId}`}>{personName}</Link> : Notes : Detail</h1><dl className="detail-list"><dt>Regarding</dt><dd>{noteRegarding(note)}</dd><dt>Notable</dt><dd>{note.text}</dd><dt>Created</dt><dd>{displayTime(note.createdAt)}{note.createdByName ? ` by ${note.createdByName}` : ""}</dd><dt>Updated</dt><dd>{displayTime(note.updatedAt)}{note.updatedByName ? ` by ${note.updatedByName}` : ""}</dd></dl><Link to={`/organizations/${organizationId}/people/${personId}/notes/${note.id}/edit`}>Edit note</Link></> : <p>Loading note…</p>}</main>; }
function TagPeople() { const { organizationId = "", tagId = "" } = useParams(); const [searchParams, setSearchParams] = useSearchParams(); const page = Math.max(1, Number(searchParams.get("page") || 1)); const pageSize = 20; const [tag, setTag] = useState<{ name: string; people: { id: string; displayName: string; staff: boolean; membershipEndsOn: string | null; lastVisitAt: string | null }[] } | null>(null); useEffect(() => { request<typeof tag>(`/api/organizations/${organizationId}/tags/${tagId}`).then(setTag).catch(() => setTag(null)); }, [organizationId, tagId]); if (!tag) return <main><OrganizationNav organizationId={organizationId} /><p>Tag not found</p></main>; const people = tag.people.slice((page - 1) * pageSize, page * pageSize); const pages = Math.max(1, Math.ceil(tag.people.length / pageSize)); return <main><OrganizationNav organizationId={organizationId} /><h1>Tag : {tag.name}</h1><p><Link to={`/organizations/${organizationId}/tags`}>All Tags</Link></p>{people.length ? <table><thead><tr><th>Person</th><th>Role</th><th>Membership ends</th><th>Last visit</th></tr></thead><tbody>{people.map((person) => <tr key={person.id}><td><Link to={`/organizations/${organizationId}/people/${person.id}`}>{person.displayName}</Link></td><td>{person.staff ? "Staff" : person.membershipEndsOn ? "Member / Patron" : "Patron"}</td><td>{person.membershipEndsOn || "—"}</td><td>{displayTime(person.lastVisitAt)}</td></tr>)}</tbody></table> : <p className="empty-state">No people have this tag.</p>}{pages > 1 && <nav className="pagination" aria-label="Tag results pages"><span>More:</span>{Array.from({ length: pages }, (_, index) => index + 1).map((number) => number === page ? <strong key={number}>{number}</strong> : <button className="link-button" key={number} onClick={() => setSearchParams({ page: String(number) })}>{number}</button>)}</nav>}</main>; }
type Visit = { id: string; personId: string; activity: "project" | "volunteering"; arrivedAt: string; startedAt: string | null; endedAt: string | null; durationSeconds: number | null; staffSnapshot?: boolean; memberSnapshot?: boolean; createdByUserId?: string | null; updatedByUserId?: string | null; createdAt?: string; updatedAt?: string; person?: { displayName: string }; note?: { text: string } | null };
const displayTime = (value: string | null) => value ? new Date(value).toLocaleString() : "—";
function VisitDay() { const { organizationId = "", day = "" } = useParams(); const [data, setData] = useState<{ today: string; previousDay: string; nextDay: string; timezone: string; visits: (Visit & { cancelledAt?: string | null })[] } | null>(null); const [error, setError] = useState(""); const [notice, setNotice] = useState(""); const load = () => request<typeof data>(`/api/organizations/${organizationId}/visits/days/${day}`).then(setData).catch((err) => setError(err.message)); useEffect(() => { void load(); }, [organizationId, day]); const transition = async (visit: Visit, action: "sign-in" | "sign-out") => { try { await request(`/api/organizations/${organizationId}/visits/${visit.id}/${action}`, { method: "POST", body: JSON.stringify({}) }); setNotice(`${visit.person?.displayName || "Person"} was successfully ${action === "sign-in" ? "signed in" : "signed out"}.`); void load(); } catch (err) { setError((err as Error).message); } }; const clock = (value: string | null) => value ? new Date(value).toLocaleTimeString([], { hour: "numeric", minute: "2-digit", timeZone: data?.timezone }) : "—"; if (!data) return <main><OrganizationNav organizationId={organizationId} notice={notice} /><p>{error || "Loading visits…"}</p></main>; const group = (activity: Visit["activity"], heading: string) => { const rows = data.visits.filter((visit) => visit.activity === activity); return <section><h2>{heading}</h2>{rows.length === 0 ? <p className="empty-state">No visits for {heading.toLowerCase()}.</p> : <table><thead><tr><th>Person</th><th>Arrived</th><th>Signed In</th><th>Signed Out</th><th>Note</th><th>Action</th></tr></thead><tbody>{rows.map((visit) => <tr key={visit.id}><td><Link to={`/organizations/${organizationId}/people/${visit.personId}`}>{visit.person?.displayName || "Person"}</Link></td><td>{clock(visit.arrivedAt)}</td><td>{clock(visit.startedAt)}</td><td>{clock(visit.endedAt)}</td><td>{visit.cancelledAt ? `Cancelled${visit.note?.text ? `: ${visit.note.text}` : ""}` : visit.note?.text || "—"}</td><td><Link to={`/organizations/${organizationId}/people/${visit.personId}/visits/${visit.id}`}>Show</Link>{!visit.cancelledAt && (!visit.startedAt ? <> · <button className="link-button" onClick={() => transition(visit, "sign-in")}>Sign In</button></> : !visit.endedAt ? <> · <button className="link-button" onClick={() => transition(visit, "sign-out")}>Sign Out</button></> : null)}</td></tr>)}</tbody></table>}</section>; }; return <main className="visit-day"><OrganizationNav organizationId={organizationId} notice={notice} /><h1>{day === data.today ? "In the Shop Today" : `In the Shop on ${day}`}</h1><p className="day-navigation"><Link to={`/organizations/${organizationId}/visits/days/${data.previousDay}`}>previous</Link>{day !== data.today && <>{" · "}<Link to={`/organizations/${organizationId}/visits/days/${data.today}`}>today</Link></>}{" · "}<Link to={`/organizations/${organizationId}/visits/days/${data.nextDay}`}>next</Link></p><p className="queue-search"><Link to={`/organizations/${organizationId}`}>Add a person to the queue</Link></p>{group("project", "Projects")}{group("volunteering", "Volunteering")}{error && <p role="alert">{error}</p>}</main>; }
function VisitForm({ edit = false }: { edit?: boolean }) { const { organizationId = "", personId = "", visitId = "" } = useParams(); const navigate = useNavigate(); const [personName, setPersonName] = useState("Person"); const [visit, setVisit] = useState({ activity: "project" as "project" | "volunteering", arrivedAt: new Date().toISOString(), startedAt: "", endedAt: "", note: "" }); const [error, setError] = useState(""); useEffect(() => { request<{ displayName: string }>(`/api/organizations/${organizationId}/people/${personId}`).then((person) => setPersonName(person.displayName)); if (edit) request<Visit>(`/api/organizations/${organizationId}/visits/${visitId}`).then((value) => setVisit({ activity: value.activity, arrivedAt: value.arrivedAt, startedAt: value.startedAt || "", endedAt: value.endedAt || "", note: value.note?.text || "" })).catch((err) => setError(err.message)); }, [edit, organizationId, personId, visitId]); const save = async (event: React.FormEvent) => { event.preventDefault(); try { const payload = { ...visit, ...(edit ? {} : { personId }), startedAt: visit.startedAt || null, endedAt: visit.endedAt || null }; const result = await request<Visit>(edit ? `/api/organizations/${organizationId}/visits/${visitId}` : `/api/organizations/${organizationId}/visits`, { method: edit ? "PUT" : "POST", body: JSON.stringify(payload) }); navigate(`/organizations/${organizationId}/people/${result.personId}/visits/${result.id}`, flash(edit ? `Visit for ${personName} was successfully updated.` : `Visit for ${personName} was successfully created.`)); } catch (err) { setError((err as Error).message); } }; const field = (key: "arrivedAt" | "startedAt" | "endedAt", label: string) => <label>{label}<input type="datetime-local" value={visit[key] ? visit[key].slice(0, 16) : ""} onChange={(event) => setVisit({ ...visit, [key]: event.target.value ? new Date(event.target.value).toISOString() : "" })} /></label>; return <main><OrganizationNav organizationId={organizationId} /><h1><Link to={`/organizations/${organizationId}/people/${personId}`}>{personName}</Link> : Visits : {edit ? "Edit" : "New"}</h1><form className="single-column-form visit-form" onSubmit={save}><label>Activity<select value={visit.activity} onChange={(event) => setVisit({ ...visit, activity: event.target.value as Visit["activity"] })}><option value="project">Project</option><option value="volunteering">Volunteer</option></select></label>{field("arrivedAt", "Arrived At")}{field("startedAt", "Signed In At")}{field("endedAt", "Signed Out At")}<label>Note<textarea value={visit.note} onChange={(event) => setVisit({ ...visit, note: event.target.value })} /></label><button>{edit ? "Update visit" : "Create visit"}</button>{error && <p role="alert">{error}</p>}</form></main>; }
function PersonVisits() { const { organizationId = "", personId = "" } = useParams(); const [searchParams, setSearchParams] = useSearchParams(); const page = Math.max(1, Number(searchParams.get("page") || 1)); const [data, setData] = useState<{ page: number; total: number; visits: Visit[] } | null>(null); const [personName, setPersonName] = useState("Person"); useEffect(() => { Promise.all([request<typeof data>(`/api/organizations/${organizationId}/people/${personId}/visits?page=${page}`), request<{ displayName: string }>(`/api/organizations/${organizationId}/people/${personId}`)]).then(([rows, person]) => { setData(rows); setPersonName(person.displayName); }); }, [organizationId, personId, page]); return <main><OrganizationNav organizationId={organizationId} /><h1><Link to={`/organizations/${organizationId}/people/${personId}`}>{personName}</Link> : Visits</h1><p><Link to={`/organizations/${organizationId}/people/${personId}/visits/new`}>New visit</Link></p>{data?.visits.length ? <table><thead><tr><th>Arrived</th><th>Signed In</th><th>Signed Out</th><th>Activity</th><th>Hours</th><th>Note</th><th>Actions</th></tr></thead><tbody>{data.visits.map((visit) => <tr key={visit.id}><td>{displayTime(visit.arrivedAt)}</td><td>{displayTime(visit.startedAt)}</td><td>{displayTime(visit.endedAt)}</td><td>{visit.activity === "volunteering" ? "Volunteer" : "Project"}</td><td>{visit.durationSeconds === null ? "—" : (visit.durationSeconds / 3600).toFixed(1)}</td><td>{visit.note?.text || "—"}</td><td><Link to={`/organizations/${organizationId}/people/${personId}/visits/${visit.id}`}>Show</Link>{" · "}<Link to={`/organizations/${organizationId}/people/${personId}/visits/${visit.id}/edit`}>Edit</Link></td></tr>)}</tbody></table> : <p className="empty-state">No visits.</p>}{data && data.total > 25 && <nav className="pagination" aria-label="Visit history pages"><button className="link-button" disabled={page === 1} onClick={() => setSearchParams({ page: String(page - 1) })}>Previous</button><span>Page {page}</span><button className="link-button" disabled={page * 25 >= data.total} onClick={() => setSearchParams({ page: String(page + 1) })}>Next</button></nav>}</main>; }
function VisitDetail() { const { organizationId = "", personId = "", visitId = "" } = useParams(); const navigate = useNavigate(); const [visit, setVisit] = useState<Visit | null>(null); const [personName, setPersonName] = useState("Person"); const [error, setError] = useState(""); useEffect(() => { Promise.all([request<Visit>(`/api/organizations/${organizationId}/visits/${visitId}`), request<{ displayName: string }>(`/api/organizations/${organizationId}/people/${personId}`)]).then(([value, person]) => { setVisit(value); setPersonName(person.displayName); }).catch((err) => setError(err.message)); }, [organizationId, personId, visitId]); const transfer = async (activity: Visit["activity"]) => { try { const next = await request<Visit>(`/api/organizations/${organizationId}/visits/${visitId}/transfer`, { method: "POST", body: JSON.stringify({ activity }) }); navigate(`/organizations/${organizationId}/people/${personId}/visits/${next.id}`, flash(`Visit for ${personName} was successfully transferred.`)); } catch (err) { setError((err as Error).message); } }; const remove = async () => { try { await request(`/api/organizations/${organizationId}/visits/${visitId}`, { method: "DELETE" }); navigate(`/organizations/${organizationId}/people/${personId}/visits`, flash(`Visit for ${personName} was successfully removed.`)); } catch (err) { setError((err as Error).message); } }; return <main><OrganizationNav organizationId={organizationId} />{visit ? <><h1><Link to={`/organizations/${organizationId}/people/${personId}`}>{personName}</Link> : Visits : Detail</h1><dl className="detail-list"><dt>Activity</dt><dd>{visit.activity === "volunteering" ? "Volunteer" : "Project"}</dd><dt>Datetime arrived</dt><dd>{displayTime(visit.arrivedAt)}</dd><dt>Signed in</dt><dd>{displayTime(visit.startedAt)}</dd><dt>Signed out</dt><dd>{displayTime(visit.endedAt)}</dd><dt>Duration</dt><dd>{visit.durationSeconds === null ? "—" : `${(visit.durationSeconds / 3600).toFixed(1)} hours`}</dd><dt>Role snapshot</dt><dd>{visit.staffSnapshot ? "Staff" : visit.memberSnapshot ? "Member" : "Patron"}</dd><dt>Note</dt><dd>{visit.note?.text || "—"}</dd>{visit.createdAt && <><dt>Created</dt><dd>{displayTime(visit.createdAt)}{visit.createdByUserId ? ` by user ${visit.createdByUserId}` : ""}</dd></>}{visit.updatedAt && <><dt>Updated</dt><dd>{displayTime(visit.updatedAt)}{visit.updatedByUserId ? ` by user ${visit.updatedByUserId}` : ""}</dd></>}</dl><div className="action-row"><Link to={`/organizations/${organizationId}/people/${personId}/visits/${visitId}/edit`}>Edit visit</Link>{!visit.startedAt && !visit.endedAt && <button onClick={remove}>Remove from queue</button>}{visit.startedAt && !visit.endedAt && <button onClick={() => transfer(visit.activity === "project" ? "volunteering" : "project")}>Transfer to {visit.activity === "project" ? "volunteering" : "project"}</button>}</div>{error && <p role="alert">{error}</p>}</> : <p>{error || "Loading visit…"}</p>}</main>; }
type ReportKind = "people" | "services" | "visits" | "summary";
type SummaryRows = { day: string; staff: number; volunteer: number; member: number; patron: number; total: number }[];
function Reports() {
  const { organizationId = "" } = useParams();
  const [kind, setKind] = useState<ReportKind>("people");
  const [after, setAfter] = useState(""); const [before, setBefore] = useState("");
  const [name, setName] = useState(""); const [personType, setPersonType] = useState("all");
  const [serviceTypes, setServiceTypes] = useState({ membership: true, earn_a_bike: true, class: true });
  const [data, setData] = useState<{ page: number; pageSize: number; total: number; rows: Record<string, unknown>[] } | null>(null);
  const [summary, setSummary] = useState<{ days: SummaryRows; weeks: SummaryRows } | null>(null);
  const load = async (target = kind, requestedPage = 1) => { const query = new URLSearchParams(); if (target === "summary") { if (after) query.set("from", after); if (before) query.set("to", before); setSummary(await request(`/api/organizations/${organizationId}/reports/summary${query.size ? `?${query}` : ""}`)); setData(null); return; } if (after) query.set("after", after); if (before) query.set("before", before); if (requestedPage > 1) query.set("page", String(requestedPage)); if (target === "people") { if (name) query.set("name", name); query.set("type", personType); } if (target === "services") query.set("serviceTypes", Object.entries(serviceTypes).filter(([, selected]) => selected).map(([type]) => type).join(",")); setData(await request(`/api/organizations/${organizationId}/reports/${target}${query.size ? `?${query}` : ""}`)); setSummary(null); };
  const select = (target: ReportKind) => { setKind(target); setData(null); setSummary(null); if (target === "summary") void load(target); };
  const exportParams = new URLSearchParams({ ...(after ? { after } : {}), ...(before ? { before } : {}), ...(name && kind === "people" ? { name } : {}), ...(kind === "people" ? { type: personType } : {}), ...(kind === "services" ? { serviceTypes: Object.entries(serviceTypes).filter(([, selected]) => selected).map(([type]) => type).join(",") } : {}) });
  const summaryTable = (heading: string, rows: SummaryRows) => <section><h2>{heading}</h2>{rows.length === 0 ? <p>No visits for date range.</p> : <table><thead><tr><th>{heading === "Visits by Week" ? "Starting" : "Day"}</th><th>Staff</th><th>Volunteers</th><th>Members</th><th>Patrons</th><th>Total</th></tr></thead><tbody>{rows.map((row) => <tr key={row.day}><td>{row.day}</td><td>{row.staff}</td><td>{row.volunteer}</td><td>{row.member}</td><td>{row.patron}</td><td>{row.total}</td></tr>)}</tbody></table>}</section>;
  const reportName = kind[0].toUpperCase() + kind.slice(1);
  const columns: Record<Exclude<ReportKind, "summary">, [string, string][]> = { people: [["displayName", "Name"], ["email", "Email"], ["phone", "Phone"], ["staff", "Staff"], ["createdAt", "Created"], ["membershipExpiresOn", "Membership expires"]], services: [["personName", "Person"], ["type", "Service type"], ["startDate", "Start date"], ["endDate", "End date"], ["paid", "Paid"], ["volunteered", "Volunteered"], ["note", "Note"]], visits: [["personName", "Person"], ["classification", "Type"], ["arrivedAt", "Arrived"], ["startedAt", "Signed in"], ["endedAt", "Signed out"], ["durationSeconds", "Hours"], ["note", "Note"]] };
  const reportValue = (key: string, value: unknown) => { if (value === null || value === undefined || value === "") return "—"; if (typeof value === "boolean") return value ? "Yes" : "No"; if (key === "type") return serviceLabel(value as Service["type"]); if (key.endsWith("At")) return displayTime(String(value)); if (key === "durationSeconds") return (Number(value) / 3600).toFixed(1); return String(value); };
  return <main><OrganizationNav organizationId={organizationId} /><h1>Reports</h1><div className="report-intro"><section><h2>People Report</h2><p>The People Report lists people, members and non-members, and can be exported as CSV.</p></section><section><h2>Visits Report</h2><p>The Visits Report lists visits in a date range and can be exported as CSV.</p></section><section><h2>Services Report</h2><p>The Services Report lists services by type in a date range and can be exported as CSV.</p></section><section><h2>Summary Report</h2><p>The Summary Report provides a high-level view of who is visiting the shop and when.</p></section></div><nav className="report-tabs" aria-label="Report type">{(["people", "services", "visits", "summary"] as ReportKind[]).map((target) => <button key={target} role="tab" aria-selected={kind === target} onClick={() => select(target)}>{target[0].toUpperCase() + target.slice(1)}</button>)}</nav><h2>Reports : {reportName}</h2><form className="report-form" onSubmit={(event) => { event.preventDefault(); void load(kind, 1); }}><fieldset className="date-range"><legend>Date Range</legend><div className="paired-fields"><label>Date From<input type="date" value={after} onChange={(event) => setAfter(event.target.value)} /></label><label>Date To<input type="date" value={before} onChange={(event) => setBefore(event.target.value)} /></label></div></fieldset>{kind === "people" && <><label>Matching name<input value={name} onChange={(event) => setName(event.target.value)} /></label><fieldset><legend>Type</legend>{["all", "staff", "patron"].map((type) => <label className="inline-choice" key={type}><input type="radio" name="personType" checked={personType === type} onChange={() => setPersonType(type)} />{type === "all" ? "All" : type === "staff" ? "Staff" : "Patrons"}</label>)}</fieldset></>}{kind === "services" && <fieldset><legend>Service Type</legend>{Object.entries(serviceTypes).map(([type, selected]) => <label className="inline-choice" key={type}><input type="checkbox" checked={selected} onChange={(event) => setServiceTypes({ ...serviceTypes, [type]: event.target.checked })} />{serviceLabel(type as Service["type"])}</label>)}</fieldset>}<button>Update report</button></form>{kind !== "summary" && data && <section><h2>{reportName}</h2><p><em>{data.total} result{data.total === 1 ? "" : "s"}.</em></p>{data.rows.length === 0 ? <p className="empty-state">No {kind} for date range.</p> : <table><thead><tr>{columns[kind].map(([key, label]) => <th key={key}>{label}</th>)}</tr></thead><tbody>{data.rows.map((row, index) => <tr key={String(row.id || index)}>{columns[kind].map(([key]) => <td key={key}>{reportValue(key, row[key])}</td>)}</tr>)}</tbody></table>}{data.total > data.pageSize && <nav className="pagination" aria-label="Report result pages"><button className="link-button" disabled={data.page === 1} onClick={() => void load(kind, data.page - 1)}>Previous</button><span>Page {data.page}</span><button className="link-button" disabled={data.page * data.pageSize >= data.total} onClick={() => void load(kind, data.page + 1)}>Next</button></nav>}<p className="export-row"><a href={`/api/organizations/${organizationId}/reports/${kind}.csv?${exportParams}`}>Export all</a></p></section>}{kind === "summary" && summary && <>{summaryTable("Visits by Week", summary.weeks)}{summaryTable("Visits by Day", summary.days)}</>}</main>;
}
function App() { const protectedPage = (page: ReactNode) => <Protected>{page}</Protected>; return <div className="app-shell"><Routes><Route path="/" element={<Login />} /><Route path="/change-password" element={<Protected allowPasswordChange><ChangePassword /></Protected>} /><Route path="/organizations/:organizationId" element={protectedPage(<People />)} /><Route path="/organizations/:organizationId/account" element={protectedPage(<Account />)} /><Route path="/organizations/:organizationId/reports" element={protectedPage(<Reports />)} /><Route path="/organizations/:organizationId/imports" element={protectedPage(<Imports />)} /><Route path="/organizations/:organizationId/bulk-management" element={protectedPage(<BulkManagement />)} /><Route path="/organizations/:organizationId/settings" element={protectedPage(<Settings />)} /><Route path="/organizations/:organizationId/visits/days/:day" element={protectedPage(<VisitDay />)} /><Route path="/organizations/:organizationId/tags" element={protectedPage(<Tags />)} /><Route path="/organizations/:organizationId/tags/:tagId" element={protectedPage(<TagPeople />)} /><Route path="/organizations/:organizationId/people/new" element={protectedPage(<PersonForm />)} /><Route path="/organizations/:organizationId/people/:personId/edit" element={protectedPage(<EditPerson />)} /><Route path="/organizations/:organizationId/people/:personId/visits/new" element={protectedPage(<VisitForm />)} /><Route path="/organizations/:organizationId/people/:personId/visits/:visitId/edit" element={protectedPage(<VisitForm edit />)} /><Route path="/organizations/:organizationId/people/:personId/visits/:visitId" element={protectedPage(<VisitDetail />)} /><Route path="/organizations/:organizationId/people/:personId/visits" element={protectedPage(<PersonVisits />)} /><Route path="/organizations/:organizationId/people/:personId/services/new" element={protectedPage(<ServiceForm />)} /><Route path="/organizations/:organizationId/people/:personId/services/:serviceId/edit" element={protectedPage(<ServiceForm edit />)} /><Route path="/organizations/:organizationId/people/:personId/services/:serviceId" element={protectedPage(<ServiceDetail />)} /><Route path="/organizations/:organizationId/people/:personId/services" element={protectedPage(<PersonServices />)} /><Route path="/organizations/:organizationId/people/:personId/tags" element={protectedPage(<PersonTags />)} /><Route path="/organizations/:organizationId/people/:personId/notes/new" element={protectedPage(<NoteForm />)} /><Route path="/organizations/:organizationId/people/:personId/notes/:noteId/edit" element={protectedPage(<NoteForm edit />)} /><Route path="/organizations/:organizationId/people/:personId/notes/:noteId" element={protectedPage(<NoteDetail />)} /><Route path="/organizations/:organizationId/people/:personId/notes" element={protectedPage(<PersonNotes />)} /><Route path="/organizations/:organizationId/people/:personId" element={protectedPage(<Profile />)} /></Routes><p className="timezone-note">Times are shown in your organization’s timezone.</p><footer><span className="footer-brand">Freehub</span><span>Community workshop management</span></footer></div>; }
createRoot(document.getElementById("root")!).render(<BrowserRouter><App /></BrowserRouter>);
